grep -rln "workflowLint\|workflowLint" js/unit-tests/*.json js/test/ 2>/dev/null | head ; echo "===" ; grep -rn "factory-sm-kicker.yml@\|yml@main\|yml@e6\|uses.*@main\|uses.*@e6\|uses.*@9bc\|uses.*@6e8\|uses.*@fd84" --include="*.js" --include="*.mjs" --include="*.cjs" --include="*.sh" . 2>/dev/null | grep -v ".git/" | head ; echo "===" ; python3 -c "
import yaml, glob
for f in sorted(glob.glob('.github/workflows/*.yml')):
    try:
        yaml.safe_load(open(f))
        print('OK  ', f)
    except Exception as e:
        print('FAIL', f, e)
"

